from pathlib import Path
import json
OUT=Path('pkstratagems/quiz/data');OUT.mkdir(exist_ok=True)
Q=[]
def add(id,level,topic,prompt,opts,right,why,loc,kind='rules'):
 Q.append({'id':id,'conceptId':id,'difficulty':level,'topic':topic,'kind':kind,'faction':None,'detachment':None,'prompt':prompt,'options':[{'id':chr(97+i),'text':t} for i,t in enumerate(opts)],'correctOptionId':chr(97+right),'explanation':why,'sources':[{'title':'Warhammer 40,000 Core Rules / bereitgestellter Regelstand 2026' if kind=='rules' else 'Redaktionelles Taktikszenario · alle Zahlen sind Aufgabenannahmen','locator':loc,'url':'https://www.warhammer-community.com/en-gb/downloads/warhammer-40000/' if kind=='rules' else ''}]})
# Rules are intentionally distinct from tactical preferences. Comparable options, no comic distractors.
add('core-e01','easy','core','Eine angeschlossene Einheit enthält einen Leader und einen Bodyguard-Trupp. Wie viele Einheiten werden für das normale Stratagem-Ziellimit betrachtet?', ['Eine gemeinsame Einheit.','Zwei getrennte Einheiten.','Eine Einheit je Modelltyp.'],0,'Eine Attached Unit gilt grundsätzlich als eine Einheit. Die Bestandteile liefern keine zusätzlichen Stratagem-Slots.','Core Rules 19.01, S.66; 15.01, S.54')
add('core-e02','easy','core','Eine Einheit ist genau auf die Hälfte ihrer Anfangsstärke reduziert. Was gilt im Battle-shock-Schritt ihrer Befehlsphase?', ['Sie prüft nur bei bestehendem Battle-shock.','Sie muss einen Battle-shock-Wurf ablegen.','Sie prüft erst unter ihrer halben Stärke.'],1,'Die bereitgestellten Regeln verlangen den Wurf bei oder unter halber Stärke und bei bereits geschockten Einheiten.','Core Rules 08.03, S.30')
add('core-e03','easy','core','Eine nicht geschockte Einheit hat in diesem Zug einen Advance ausgeführt. Welche Tätigkeit ist ohne Sonderregel danach gesperrt?', ['Das Beanspruchen eines Missionsziels.','Das Ausführen einer Fernkampfattacke.','Das Beginnen einer Missionsaktion.'],2,'Ein Advance verhindert in diesem Regelstand grundsätzlich Charge und Aktionsbeginn; er beseitigt nicht einfach die OC und verbietet nicht pauschal jedes Schießen.','Core Rules 09.06, S.33; 16.01, S.58')
add('core-e04','easy','core','Wann wird Rapid Ingress regulär eingesetzt?', ['Am Ende der gegnerischen Bewegungsphase.','Am Anfang der gegnerischen Bewegungsphase.','Am Ende der gegnerischen Angriffsphase.'],0,'Das Timing ist das Ende der gegnerischen Bewegungsphase; die erste Schlachtrunde ist ausdrücklich ausgeschlossen.','Core Rules 15.07, S.57')
add('core-e05','easy','core','Eine Einheit besitzt einen Bewegungswert von 12″ und nutzt Take to the Skies ohne Hover für eine normale Bewegung. Welches Maximum gilt?', ['12″ Bewegung.','10″ Bewegung.','14″ Bewegung.'],1,'Take to the Skies reduziert das jeweilige Bewegungsmaximum um 2″.','Core Rules 21.03, S.71')
add('core-e06','easy','core','Ein Charge-Wurf ergibt 7. Ein Gegner steht 8″ entfernt. Darf er ohne weitere Regeln als Charge-Ziel gewählt werden?', ['Ja, weil 2″ Engagement Range genügen.','Ja, weil der Gegner innerhalb 12″ steht.','Nein, weil er außerhalb des Maximums steht.'],2,'Das Ziel muss innerhalb 12″ UND innerhalb des erwürfelten Maximums liegen. Die Möglichkeit, theoretisch in Engagement Range zu enden, ersetzt diese Voraussetzung nicht.','Core Rules 11.04, S.37')
add('core-e07','easy','core','Wann wird Insane Bravery im normalen Ablauf angesagt?', ['Vor dem Battle-shock-Wurf im eigenen Schritt.','Nach dem Battle-shock-Wurf im eigenen Schritt.','Vor einem beliebigen Battle-shock-Wurf im Spiel.'],0,'Das Stratagem wird im Battle-shock-Schritt der eigenen Befehlsphase vor dem Wurf eingesetzt und ist einmal pro Schlacht erlaubt.','Core Rules 15.04, S.56')
add('core-e08','easy','core','Wie wird ein normaler Hazard-Wurf in den bereitgestellten Grundregeln ausgewertet?', ['Bei 1 scheitert er; eine tödliche Wunde.','Bei 1–2 scheitert er; eine tödliche Wunde.','Bei 1–3 scheitert er; eine tödliche Wunde.'],1,'Ein Hazard-Wurf scheitert auf 1–2. Besteht die gesamte Einheit aus Monster-/Vehicle-Modellen, sind es stattdessen drei tödliche Wunden.','Core Rules 06.03, S.24')
add('core-e09','easy','core','Eine Einheit soll eine zweite Aktion im selben Zug beginnen. Beide Aktionen hätten verschiedene Namen. Was gilt ohne Ausnahme?', ['Erlaubt, wenn die erste Aktion beendet ist.','Erlaubt, wenn beide Aktionen sofort enden.','Gesperrt, weil schon eine Aktion begonnen wurde.'],2,'Die Beschränkung betrifft jede zuvor in diesem Zug gestartete Aktion, nicht nur eine Aktion gleichen Namens.','Core Rules 16.01, S.58')
add('core-e10','easy','core','Welche Nahkampf-Reihenfolge gehört zu diesem Regelstand?', ['Pile-ins, Kämpfe, Consolidations.','Einzelweise Pile-in, Kampf, Consolidation.','Kämpfe, Pile-ins, Consolidations.'],0,'Pile-ins und Consolidations sind eigene gemeinsame Schritte. Nicht den individuellen Aktivierungsablauf einer anderen Edition übernehmen.','Core Rules 12.02–12.08, S.38–42')
add('core-m01','medium','core','Ein Charge-Wurf besteht aus einer 2 und einer 3. Du nutzt Command Re-roll. Was wird neu gewürfelt?', ['Nur ein ausgewählter Würfel.','Beide Würfel dieses Charge-Wurfs.','Die niedrigere gewürfelte Zahl.'],1,'Für gemeinsam geworfene Würfel wird sonst ein Würfel gewählt; Charge-Würfe werden ausdrücklich vollständig wiederholt.','Core Rules 15.02, S.56')
add('core-m02','medium','core','Du wiederholst mit Command Re-roll einen Schadenswurf von 2W6. Was wird ohne weitere Ausnahme neu gewürfelt?', ['Beide Würfel des Schadenswurfs.','Jeder Würfel unter seinem Mittelwert.','Ein ausgewählter Würfel des Wurfs.'],2,'Bei gemeinsam geworfenen Würfeln wird ein Würfel gewählt. Die Ausnahme für vollständiges Wiederholen betrifft Charge-Würfe.','Core Rules 15.02, S.56')
add('core-m03','medium','core','Ein Leader hat T6, sein letzter Bodyguard T4. Welche Toughness wird für eine Attacke auf die Attached Unit verwendet?', ['T4, solange ein Bodyguard vorhanden ist.','T6, weil der Leader den höheren Wert hat.','T5, als Mittelwert der beiden Modelle.'],0,'Solange Bodyguard-Modelle vorhanden sind, wird deren höchste Toughness verwendet.','Core Rules 19.02, S.66')
add('core-m04','medium','core','Ein Psyker führt eine Einheit nicht-psionischer Bodyguards. Eine Waffe mit Anti-Psyker 4+ greift die Einheit an. Was gilt?', ['Die Fähigkeit gilt erst gegen den Leader.','Die Fähigkeit gilt gegen die gesamte Einheit.','Die Fähigkeit gilt nur bei zusätzlichen Precision.'],1,'Die Einheit besitzt alle Keywords ihrer Bestandteile. Die einzelnen Bodyguards werden dadurch keine Psyker-Modelle, die Attacken zielen aber auf die Einheit.','Core Rules 19.03, S.67')
add('core-m05','medium','core','Eine Einheit wird nach ihrem Advance entfernt und im selben Zug wieder aufgestellt. Darf sie nun ohne Ausnahme eine Aktion beginnen?', ['Ja, nach einer Aufstellung im eigenen Gebiet.','Ja, durch den Reset ihrer Bewegungsart.','Nein, ihr Advance bleibt für den Zug bestehen.'],2,'Repositionieren löscht einen im selben Zug ausgeführten Advance, Fall Back oder Disembark nicht.','Core Rules 20.02, S.68')
add('core-m06','medium','core','Eine Einheit startet eine Aktion mit sofortigem Abschluss. Darf sie anschließend im selben Zug regulär chargen?', ['Nein, der Aktionsbeginn sperrt den Charge.','Ja, weil die Aktion schon abgeschlossen ist.','Ja, wenn noch kein Gegner ausgewählt wurde.'],0,'Der Aktionsbeginn sperrt die Charge-Erlaubnis bis zum Ende des Zuges, unabhängig von der Abschlussdauer.','Core Rules 16.01, S.58')
add('core-m07','medium','core','Eine Einheit aus drei Modellen hat bei jedem Modell einen Nachbarn in 2″; die beiden äußeren Modelle stehen 10″ auseinander. Ist sie kohärent?', ['Ja, weil eine durchgehende Kette existiert.','Nein, weil die Gesamtdistanz zu groß ist.','Ja, weil sie weniger als sieben Modelle hat.'],1,'Jedes Modell muss zusätzlich innerhalb 9″ horizontal und 5″ vertikal von jedem anderen Modell liegen.','Core Rules 03.03, S.14')
add('core-m08','medium','core','Bei Snap Shooting hat eine Einheit einen Treffer-Re-roll und +1 auf Trefferwürfe. Welche Treffer würfelst du regulär?', ['Unmodifizierte 6; Fehlschläge wiederholen.','Modifizierte 6; Fehlschläge wiederholen.','Unmodifizierte 6; keine Treffer wiederholen.'],2,'Snap Shooting verlangt unmodifizierte 6 und verbietet Treffer-Re-rolls. Andere ausdrücklich automatisch treffende Fähigkeiten gesondert prüfen.','Core Rules 15.09, S.57')
add('core-m09','medium','core','Der letzte Bodyguard stirbt, der angeschlossene Leader lebt. Wird eine Regel „wenn eine Einheit zerstört wird“ dadurch bereits ausgelöst?', ['Nein, erst wenn das letzte Anfangsmodell fällt.','Ja, weil der Bodyguard-Trupp ausgelöscht wurde.','Ja, falls der Trupp mindestens fünf Modelle hatte.'],0,'Die bereitgestellten Attached-Unit-Regeln lösen solche Effekte erst aus, wenn das letzte Modell dieser ursprünglichen Attached Unit zerstört wurde.','Core Rules 19.02, S.66')
add('core-m10','medium','core','Eine Einheit beendet Engaging Consolidation in Kontakt mit einem Gegner, der diese Phase noch nicht gekämpft hat. Was passiert?', ['Der Gegner bleibt bis zur nächsten Phase inaktiv.','Der Gegner wird noch zum Kämpfen ausgewählt.','Der Gegner kämpft nur mit Fights First zurück.'],1,'Der neu gebundene Gegner wird noch zum Kampf ausgewählt. Die Consolidation ist keine automatische kostenlose Bindung.','Core Rules 12.08, S.42')
add('core-h01','hard','core','Du hast 2 CP. Ein Stratagem kostet 2 CP. Eine unbenannte Fähigkeit setzt Kosten auf 0 CP; ein gegnerischer Effekt erhöht diese Nutzung um 1 CP. Welche Kosten resultieren nach dem bereitgestellten Universal Update?', ['1 CP.','3 CP.','2 CP.'],2,'Die unbenannte 0-CP-Fähigkeit wird zu −1 CP. Zusammen mit +1 CP bleibt der ursprüngliche Preis von 2 CP. Es gibt dadurch keine zusätzliche Nutzung.','Universal Rules Updates v1.1, Abschnitt Modifying a Stratagem’s CP Cost')
add('core-h02','hard','core','Ein Bodyguard verleiht seiner Attached Unit eine Einheitenfähigkeit. Sein letztes Modell stirbt durch die erste Attacke einer gegnerischen Einheit. Wie lange bleibt die Fähigkeit für diesen Angriff bestehen?', ['Bis die gegnerische Einheit alle Attacken beendet.','Bis die nächste Attacke dieser Waffe begonnen wird.','Bis die gesamte laufende Phase abgeschlossen ist.'],0,'Wird das letzte Quellmodell durch eine Attacke zerstört, bleibt der Effekt bis zum Abschluss aller Attacken der angreifenden Einheit bestehen.','Core Rules 19.04, S.67')
add('core-h03','hard','core','Eine Einheit ist in dieser Phase bereits normal bewegt worden. Danach löst ihre Fähigkeit eine Surge-Bewegung aus; sie ist unengaged und nicht geschockt. Was verhindert die Surge-Bewegung?', ['Die normale Bewegung in derselben Schlachtrunde.','Die bereits erfolgte Bewegung in derselben Phase.','Die fehlende Charge-Erklärung im selben Spielerzug.'],1,'Eine Surge-Bewegung verlangt unter anderem, dass die Einheit in dieser Phase noch nicht bewegt wurde.','Core Rules 21.02, S.70')
add('core-h04','hard','core','Eine Einheit mit eigenem Leader-Buff startet angeschlossen. Alle Bodyguards sterben, der Leader lebt. Welche Aussage zum eigenen „while leading“-Buff ist nach dem bereitgestellten Regeltext zutreffend?', ['Er endet mit dem letzten Bodyguard-Modell.','Er endet mit der laufenden gegnerischen Phase.','Er bleibt beim Leader mit erfüllter Startbedingung.'],2,'Die Fußnote zu 19.04 lässt Leader/Support ihre eigenen while-leading-Fähigkeiten weiter nutzen, sofern sie angeschlossen begonnen haben. Keine Verallgemeinerung auf Fähigkeiten zerstörter Bodyguards.','Core Rules 19.04, Fußnote, S.67')
add('core-h05','hard','core','Normale Reserven, keine Sonderregel: Ein Transport hat vor Ende der dritten Schlachtrunde einen Ingress ausgeführt. Seine Insassen haben selbst noch keinen Ingress gemacht. Was gilt beim Reserven-Stichtag?', ['Die Insassen fallen unter die Transport-Ausnahme.','Die Insassen werden trotz Transportankunft zerstört.','Die Insassen müssen sofort eine Notausladung machen.'],0,'Einheiten an Bord eines Transports, der bereits einen Ingress ausgeführt hat, sind vom genannten Zerstörungs-Stichtag ausgenommen.','Core Rules 20.03–20.04, S.69')
add('core-h06','hard','core','Du erzielst 15 Primärpunkte in Schlachtrunde fünf und anschließend 10 Primärpunkte am Spielende. Vor Runde fünf hattest du 25 Primärpunkte. Wie viele Primärpunkte zählen insgesamt im Event Companion?', ['40 Primärpunkte.','45 Primärpunkte.','50 Primärpunkte.'],1,'Der End-of-Battle-Bonus liegt außerhalb des 15-Punkte-Rundenlimits, aber nicht außerhalb der 45-Punkte-Kategoriegrenze: 25+15+10 wird auf45 begrenzt.','Event Companion v1.2, S.2 und FAQ S.4')
add('core-h07','hard','core','Eine geschockte Einheit wird im selben Zug repositioniert und steht anschließend außerhalb einer zuvor wirkenden Aura. Welche Zustände werden dadurch behalten?', ['Battle-shock und die entfernte Aura.','Die entfernte Aura, aber kein Battle-shock.','Battle-shock, aber nicht die entfernte Aura.'],2,'Dauerhafte Zustände bleiben bestehen; eine an Entfernung gebundene Aura wirkt nicht außerhalb ihrer Reichweite.','Core Rules 20.02, S.68')
add('core-h08','hard','core','Einheiten A und B möchten in derselben Phase verschiedene Stratagems verwenden. A hat bereits ein eigenes Stratagem erhalten, B noch keines. Keine Ausnahmeregel gilt. Welche weitere Nutzung ist zulässig?', ['Ein anderes Stratagem auf B, nicht auf A.','Ein anderes Stratagem auf A, nicht auf B.','Ein anderes Stratagem auf A und auch auf B.'],0,'Neben dem Verbot der mehrfachen Nutzung desselben Stratagems gilt grundsätzlich ein eigenes Stratagem pro Einheit und Phase.','Core Rules 15.01, S.54')
add('core-h09','hard','core','Vor einem Heroic-Intervention-Wurf wählst du Into the Fray. Das Ergebnis ist nach Modifikatoren 9; Gegner A steht 5″, Gegner B 7″ entfernt. Welches Ziel kann ohne andere Regeln gewählt werden?', ['Gegner A und Gegner B.','Gegner A, nicht Gegner B.','Gegner B, nicht Gegner A.'],1,'Into the Fray begrenzt das modifizierte Maximum auf6 und verlangt Ziele innerhalb6 UND innerhalb dieses Maximums.','Core Rules 15.11, S.57')
add('core-h10','hard','core','In einer Attached Unit gibt es einen verwundeten Nicht-Character und einen verwundeten Character sowie unverwundete Bodyguards. Welche Gruppe kommt bei normalen Attacken zuerst in der Allocation Order?', ['Die Gruppe des verwundeten Characters.','Die Gruppe der unverwundeten Bodyguards.','Die Gruppe des verwundeten Nicht-Characters.'],2,'Eine Nicht-Character-Gruppe mit verwundetem Modell wird zuerst gewählt. Character-Gruppen dürfen nicht vor Nicht-Character-Gruppen liegen.','Core Rules 05.03, S.19')
# Tactical items: ALL options are legal under the stated scenario. The objective is explicit.
def tactic(n,l,p,o,c,w):add('tactics-'+n,l,'tactics',p,o,c,w,'Aufgabenannahmen; Entscheidungsempfehlung, keine zusätzliche Spielregel.','tactics')
tactic('e01','easy','Letzter eigener Zug. Du liegst 3 Punkte zurück. Alle übrigen Wertungen sind abgeschlossen. Trupp A kann entweder eine sichere 4-Punkte-Aktion beenden oder einen Panzer angreifen, dessen Zerstörung 2 Punkte bringt. Beide Wege sind legal. Welche Priorität gewinnt unter diesen Angaben?', ['Mit A den Panzer angreifen.','Mit A die Aktion durchführen.','Mit A den Rückraum absichern.'],1,'Die Aktion bringt den nötigen Vorsprung. Der Panzer-Kill reicht selbst im Erfolgsfall nicht. Rückraumschutz hat ohne weitere Wertung hier keinen Ergebnisnutzen.')
tactic('e02','easy','Du kannst ein Missionsziel mit einem 60-Punkte-Trupp oder einem 220-Punkte-Kampftrupp sicher halten. Beide haben dafür genügend OC und sind dort gleich sicher. Nur der Kampftrupp kann nebenan den nächsten Angriff abfangen. Welche Verteilung ist vorzuziehen?', ['Den Kampftrupp halten lassen.','Beide Trupps am Ziel belassen.','Den kleinen Trupp halten lassen.'],2,'Unter gleichen Haltebedingungen erzeugt der kleine Trupp weniger Opportunitätskosten. Der Kampftrupp bleibt für die Aufgabe verfügbar, die nur er erfüllen kann.')
tactic('e03','easy','Du führst deutlich. Noch zwei gegnerische Züge. Dein einziger mobiler Gegenangriff kann entweder hinter einer Sichtblockade bleiben oder einen unwichtigen 40-Punkte-Trupp töten und danach sicher ausgeschaltet werden. Der kleine Gegner kann keine Punkte mehr beeinflussen. Welche Wahl schützt die Führung besser?', ['Die Gegenangriffseinheit erhalten.','Den kleinen Gegner sofort töten.','Die beiden Halter zum Angriff schicken.'],0,'Die erhaltene Drohung schützt zukünftige Haltepunkte. Ein sicherer Austausch gegen eine wertungsirrelevante Einheit verbessert den Spielstand nicht.')
tactic('e04','easy','Zwei feindliche Einheiten sind gleich leicht zu entfernen. X verursacht wenig Schaden, beendet aber diesen Zug eine 5-Punkte-Aktion. Y verursacht mehr Schaden, kann euren Haltern vor Spielende aber nicht mehr schaden und bringt keinen Kill-Score. Du kannst nur eine angreifen. Welche Priorität ist besser?', ['Die starke Kampfeinheit Y angreifen.','Den aktiven Missionshelfer X angreifen.','Beide Ziele mit halber Kraft angreifen.'],1,'Hier ist der Wertungsweg von X der relevante Unterschied. Der nominelle Schaden von Y wirkt sich im verbleibenden Spiel nicht mehr aus; Splitten gefährdet den zuverlässigen Denial.')
tactic('e05','easy','Eine abgesicherte Primäraktion bringt 4 Punkte. Ein zusätzlicher Vorstoß bringt 2 Punkte, lässt aber denselben Aktionshelfer vor dem Abschluss sicher sterben. Beide Bewegungen sind legal; keine anderen Gewinne entstehen. Was ist vorzuziehen?', ['Den Vorstoß für zwei Punkte wählen.','Beide Aufgaben demselben Helfer geben.','Die geschützte Primäraktion wählen.'],2,'Der Zusatzgewinn kostet die höher bewertete sichere Aktion. Zwei nominelle Aufgaben ergeben keinen gemeinsamen Gewinn, wenn der Helfer vor dem Abschluss stirbt.')
tactic('e06','easy','Ein feindlicher Hauptblock kann diese Runde nur den linken Bereich erreichen. Rechts sind zwei erreichbare Wertungsflächen frei. Ein Kampf links wäre unsicher; rechts können eure Helfer ohne weiteren Nachteil punkten. Welche Schwerpunktwahl ist vorzuziehen?', ['Die freien rechten Flächen nutzen.','Den gesamten Angriff links bündeln.','Die Helfer bis nächste Runde parken.'],0,'Der Gegner muss nicht besiegt werden, um seine Reichweite taktisch zu umgehen. Die Aufgabenannahmen belohnen freie Räume, nicht den prestigeträchtigen Frontalkampf.')
tactic('e07','easy','Zwei gleich zuverlässige Angriffe nehmen denselben gegnerischen Halter. Route A endet offen und verliert danach die eigene Einheit; Route B endet geschützt und behält denselben Punktgewinn. Reichweiten und Bewegungen sind legal. Welche Route ist besser?', ['Die offene Route A wählen.','Die geschützte Route B wählen.','Auf beide Angriffswege verzichten.'],1,'Gleicher unmittelbarer Ertrag bei besserer Erhaltung macht B unter den gegebenen Bedingungen vorzuziehen. Es gibt keinen genannten Zusatznutzen für die offene Position.')
tactic('e08','easy','Du hast zwei kleine Helfer und zwei sichere Aktionsorte. Jeder Ort kann in diesem Zug nur einmal gewertet werden. Beide Helfer erreichen beide Orte ohne Risiko. Wie nutzt du sie am besten?', ['Beide auf den ersten Ort schicken.','Einen einsetzen, den anderen parken.','Je einen an jedem Ort einsetzen.'],2,'Die Trennung nutzt beide Wertungsmöglichkeiten. Eine doppelte Besetzung derselben einfachen Aufgabe erzeugt hier keinen weiteren Gewinn.')
tactic('e09','easy','Du benötigst noch einen sicheren Halter für deinen nächsten Zug. Ein frischer Trupp und ein fast zerstörter Trupp haben genügend OC. Am Ziel überlebt nur der frische Trupp den bekannten gegnerischen Beschuss zuverlässig. Die andere Aufgabe ist ungefährlich. Wie teilst du zu?', ['Den frischen Trupp am Ziel einsetzen.','Den angeschlagenen Trupp dort einsetzen.','Beide Trupps für die Nebenaufgabe nutzen.'],0,'OC allein reicht für eine spätere Wertung nicht. Der relevante Halter muss bis dahin überleben; der angeschlagene Trupp kann die sichere Nebenaufgabe übernehmen.')
tactic('e10','easy','Dein Verbündeter kann den billigen Screen sicher im Beschuss entfernen. Dein Nahkampfverband kann danach den wertungsrelevanten Gegner dahinter legal angreifen. Ohne diesen Beschuss bleibt er am Screen hängen. Welche Reihenfolge ist vorzuziehen?', ['Mit dem Verband den Screen bekämpfen.','Den Screen zuerst gezielt beschießen.','Den Beschuss auf den hinteren Gegner teilen.'],1,'Der vorbereitende Beschuss setzt die knappe Nahkampfaktivierung für ihr relevantes Ziel frei. Der Screen ist kein guter Einsatz für den teuren Verband, wenn er anders zuverlässig entfernt werden kann.')
tactic('e11','easy','Du hast 1 CP. Ein Re-roll kann einen bereits unnötig hohen Schaden weiter erhöhen; ein späterer defensiver Einsatz sichert laut Aufgabe denselben Zug einen 4-Punkte-Halter. Beide Anwendungen wären legal. Wo ist der CP vorzuziehen?', ['Beim zusätzlichen Schadenswurf einsetzen.','Den CP am Ende ungenutzt behalten.','Für den Schutz des Halters reservieren.'],2,'Der erste Einsatz ändert kein Ergebnis, der zweite sichert Punkte. Ressourcen sollen die entscheidende Schwelle beeinflussen, nicht bloß die höchste Schadenszahl.')
tactic('e12','easy','Eine bereits ausreichend besetzte Flanke benötigt keine Verstärkung. Die zweite Flanke hat genau einen angreifbaren Aktionshelfer. Dein mobiler Trupp kann eine von beiden legal decken, weitere Folgen sind ausgeschlossen. Wo ist er nützlicher?', ['Den gefährdeten Aktionshelfer decken.','Die bereits sichere Flanke verstärken.','Zwischen beiden außerhalb Reichweite stehen.'],0,'Die zusätzliche Einheit verhindert auf der zweiten Flanke einen konkreten Ausfall. Auf der ersten verbessert sie unter den angegebenen Annahmen nichts.')
tactic('m01','medium','Ziel ist der höchste erwartete zusätzliche Punktgewinn dieses Zuges; Risiken für spätere Züge entfallen. Angriff A bringt mit 75 % vier Punkte, Angriff B mit 40 % acht Punkte; bei Fehlschlag jeweils null. Eine dritte Route bringt sicher drei. Welche Wahl ist rechnerisch vorzuziehen?', ['Angriff A für vier Punkte versuchen.','Angriff B für acht Punkte versuchen.','Die sichere Drei-Punkte-Route nehmen.'],1,'A: 0,75×4=3. B:0,40×8=3,2. Sicher:3. Für das ausdrücklich genannte Erwartungswertziel liegt B knapp vorn; eine Siegchancen-Frage könnte anders ausfallen.')
tactic('m02','medium','Letzter Zug, Rückstand 5. Alle anderen Punkte stehen fest. A bringt sicher vier Punkte, B mit 60 % sechs Punkte und sonst null, C mit 40 % neun und sonst null. Gesucht ist die höchste Siegchance, nicht der Erwartungswert. Welche Wahl?', ['Die sichere Vier-Punkte-Route A.','Die Sechspunkt-Route B mit 60 %.','Die Neunpunkt-Route C mit 40 %.'],1,'A verliert sicher. B gewinnt in60%, C in40%. Überzählige Siegpunkte erhöhen hier nicht die Gewinnchance.')
tactic('m03','medium','Du führst im Endspiel. Um zu gewinnen, muss der Gegner beide verbleibenden Ziele nehmen. Deine letzte Reserve kann ein Ziel sicher halten oder beide mit je 50 % Haltechance unterstützen. Andere Effekte sind ausgeschlossen. Welche Verteilung schützt den Sieg besser?', ['Beide Ziele mit halber Stärke decken.','Die Reserve zum gegnerischen Heimziel schicken.','Ein entscheidendes Ziel sicher halten.'],2,'Ein garantiert gehaltenes Ziel bricht die notwendige Doppelerfüllung. Breite halbe Absicherung lässt einen Weg offen; der Angriff auf ein unwichtiges Heimziel hilft nicht.')
tactic('m04','medium','Zwei feindliche Halter können identisch angegriffen werden. Das Entfernen von X verhindert 4 gegnerische Punkte; das Entfernen von Y verhindert2 und öffnet sicher3 eigene. Eigene Kategoriegrenzen greifen noch nicht. Welche Wahl maximiert die Punktedifferenz?', ['Den Halter X angreifen.','Den Halter Y angreifen.','Beide Halter nur anschlagen.'],1,'X verbessert die Differenz um4. Y verbessert sie um2+3=5. Denial und eigener Zugewinn müssen zusammen betrachtet werden.')
tactic('m05','medium','Zug4, du spielst zuerst. Der äußere Helfer bringt jetzt3 Punkte, ist danach sicher verloren; der innere Helfer bringt jetzt2 und in Zug5 noch4 sicher. Du kannst nur einen Weg wählen. Keine weiteren Folgen. Welche Wahl bringt über beide Züge mehr?', ['Den äußeren Helferweg wählen.','Den inneren Helferweg wählen.','Beide Helfer bis Zug5 zurückhalten.'],1,'Der innere Weg bringt2+4=6 gegenüber3. Die frühe Einzelwertung ist nicht automatisch die beste Entscheidung über den verbleibenden Zeithorizont.')
tactic('m06','medium','Du benötigst einen Kill zur Freigabe einer Aktion. Trupp A schafft den Kill mit90%, B mit60%. A wird nächste Runde zwingend zum Abfangen einer Bedrohung gebraucht; B hat danach keine weitere Aufgabe. A kann B nach dessen Scheitern noch unterstützen. Welche Aktivierungsfolge ist besser?', ['Zuerst A, danach B einsetzen.','A und B sofort gemeinsam binden.','Zuerst B, A als Absicherung halten.'],2,'Die schwächere, sonst ungebundene Einheit bekommt die erste Chance. A bleibt bei Erfolg für seine einzigartige nächste Aufgabe frei und kann bei Bedarf noch absichern.')
tactic('m07','medium','Die Primärgrenze ist bereits erreicht. Ein Missionsziel würde dir nominell vier weitere Primärpunkte geben. Eine alternative Position verhindert sicher drei gegnerische Punkte. Keine Sekundär- oder Endboni sind betroffen. Welche Option ist besser?', ['Die gegnerische Wertung verhindern.','Das zusätzliche Primärziel nehmen.','Beide Positionen kampflos aufgeben.'],0,'Punkte oberhalb der eigenen Grenze zählen nicht. Der gegnerische Denial verändert dagegen die Punktedifferenz.')
tactic('m08','medium','Du kannst nach dem Kampf legal am sicheren Ziel bleiben oder in einen frischen Gegner consolidaten. Er hat noch nicht gekämpft und entfernt deinen Halter dann sicher. Das Binden verhindert keine weitere Bewegung/Wertung vor Spielende. Was ist vorzuziehen?', ['In den frischen Gegner consolidaten.','Am sicheren Missionsziel bleiben.','Die Zielkontrolle freiwillig aufgeben.'],1,'Der freiwillige Nahkampf bietet hier nur das Risiko eines unmittelbaren Rückschlags ohne Wertungsnutzen. Das Halten bewahrt die sichere Position.')
tactic('m09','medium','Eine Flanke hat einen robusten Halter, die andere nur einen kleinen Helfer. Dein Gegner kann mit einem Angriff eine der beiden bedrohen. Dein Konter erreicht beide, solange er zentral bleibt; vorgezogen erreicht er nur die robuste Seite. Welche Stellung ist vorzuziehen?', ['Den Konter zur robusten Flanke ziehen.','Den Konter an den Rand zurückziehen.','Den Konter zentral gedeckt halten.'],2,'Die zentrale Drohung hält zwei Antworten offen und schützt gerade den verwundbaren Helfer. Ohne zusätzlichen Gewinn wäre die frühe Festlegung ein Flexibilitätsverlust.')
tactic('m10','medium','Für eine Aktion brauchst du eine leere gegnerische Geländegrundfläche am Zugende. Dort stehen zwei Gegner. Ein Angriff kann nur einen entfernen, ein zweiter Verband kann den anderen erreichen. Beide stehen nächste Runde nicht für andere Aufgaben an. Was ist vorzuziehen?', ['Beide Gegner für den Abschluss entfernen.','Nur den stärkeren Gegner dort entfernen.','Den Helfer ohne Räumung dorthin schicken.'],0,'Die Leerheitsbedingung verlangt, dass kein Gegner bleibt. Der Schaden am stärkeren Ziel allein macht aus dieser Aktion noch keinen Erfolg; beide Verbände haben laut Aufgabe keine konkurrierende Pflicht.')
tactic('m11','medium','Eine 1-CP-Verbesserung hebt die Killchance von50 auf80%. Ein anderer legaler 1-CP-Einsatz hebt die Chance, einen 6-Punkte-Halter zu erhalten, von70 auf90%. Der Kill bringt3 Punkte. Weitere Folgen gibt es nicht. Welcher Einsatz hat mehr erwarteten Punktewert?', ['Die Verbesserung der Killchance.','Die Verbesserung der Haltechance.','Beide Einsätze haben gleichen Wert.'],1,'Kill:0,30×3=0,9 erwartete Zusatzpunkte. Halter:0,20×6=1,2. Nicht nur die größere prozentuale Chancenänderung vergleichen.')
tactic('m12','medium','Zug3: Ein markiertes Ziel liefert laut Aufgabenregel weiter Punkte, auch wenn du es nicht hältst. Ein frisches Ziel kann nur mit dem dortigen Trupp erreicht werden. Es gibt keine gegnerische Gefahr für das alte Ziel und keine sonstige Haltewertung. Welche Wahl ist besser?', ['Den Trupp am alten Ziel verdoppeln.','Den Trupp ohne Aufgabe zurückziehen.','Den Trupp zum frischen Ziel verlagern.'],2,'Die persistierende Markierung benötigt in dieser Aufgabenannahme keinen dauerhaften Halter. Die Einheit kann ihren nächsten messbaren Wert am frischen Ziel schaffen.')
tactic('h01','hard','Letzter Zug, du liegst4 zurück. A erzielt sicher4 (Unentschieden), B gewinnt mit55% durch5 Punkte, C erzielt mit90% drei Punkte und sonst0. Es gibt keine anderen Scores. Dein Ziel ist ausschließlich ein Sieg. Welche Option?', ['Den sicheren Ausgleich A wählen.','Die Siegchance über B wählen.','Die hohe Erfolgsquote C wählen.'],1,'Erfolgsquote und Siegchance sind nicht dasselbe. Nur B hat unter diesen Ergebnissen eine positive Gewinnchance. Ein Ziel „Niederlage vermeiden“ würde A bevorzugen.')
tactic('h02','hard','Ein Angriff bringt mit70% sechs eigene Punkte, kostet dann aber sicher einen Halter mit3 Punkten im nächsten Zug. Bei Fehlschlag fallen beide Gewinne aus und der Halter geht ebenfalls verloren. Alternativ bleibt der Halter sicher erhalten; sonst entstehen keine Punkte. Was maximiert den Erwartungswert über beide Züge?', ['Den Angriff für sechs Punkte nehmen.','Den Halter sicher am Ziel behalten.','Den Halter ohne Angriff zurückziehen.'],0,'Angriff erzielt0,70×6=4,2 Gesamtpunkte, Halten3. Der Verlust des Halters ist im Alternativenvergleich enthalten; nicht4,2−3 mit3 vergleichen und dessen Kosten doppelt zählen. Es geht um Erwartungswert, nicht um Überlebenswahrscheinlichkeit.')
tactic('h03','hard','Zwei unabhängige Aufgaben bringen je4 Punkte und sind beide nötig, um den Rückstand aufzuholen. Ohne CP gelingen sie mit60% und80%. Dein einziger CP erhöht wahlweise die erste auf80% oder die zweite auf95%. Welche Verbesserung erhöht die gemeinsame Erfolgswahrscheinlichkeit stärker?', ['Die zweite Aufgabe auf95% erhöhen.','Den CP für spätere Schäden behalten.','Die erste Aufgabe auf80% erhöhen.'],2,'Erste verbessern:0,80×0,80=64%. Zweite verbessern:0,60×0,95=57%. Die schwächere Kette bekommt hier den wertvolleren Eingriff.')
tactic('h04','hard','Du führst um2. Der Gegner gewinnt genau dann, wenn seine beiden unabhängigen Aktionen für je3 Punkte gelingen. Aktuell haben beide80%. Du kannst eine auf20% senken oder beide auf50%. Welche Abwehr minimiert seine Siegchance?', ['Eine Aktion auf20% senken.','Beide Aktionen auf50% senken.','Nur seinen Kampftrupp ausschalten.'],0,'Die Aufgabe legt fest, dass beide Aktionen nötig sind. Eine auf20% ergibt0,2×0,8=16% Gegnersieg, beide auf50% ergeben25%. Ein unbeteiligter Kampftrupp ändert nichts. Die angegebenen Siegbedingungen sind hier entscheidend.')
tactic('h05','hard','Am Ende dieses Zuges sind noch2 Primärpunkte bis zum Kategorienlimit frei. Angriff A schafft mit80% einen 4-Punkte-Primärgewinn. Angriff B verhindert mit60% drei gegnerische Punkte. Ansonsten keine Folgen. Welche Wahl maximiert die erwartete Differenz?', ['Den Primärgewinn mit A suchen.','Die gegnerische Wertung mit B stören.','Beide Angriffe gar nicht ausführen.'],1,'A kann nur2 Punkte anrechnen:0,8×2=1,6. B bringt0,6×3=1,8 Differenz. Rohwert und Kategoriegrenze müssen vor dem Chancenvergleich zusammengeführt werden.')
tactic('h06','hard','Ein 1-CP-Werkzeug kann heute den Verlust eines 4-Punkte-Halters mit25 Prozentpunkten geringerer Wahrscheinlichkeit verhindern. Aufheben ermöglicht morgen sicher einen sonst unmöglichen 2-Punkte-Abschluss. Beide Anwendungen sind legal; spätere Unsicherheit und neue CP entfallen. Welche Priorität ist besser?', ['Den Halter heute zusätzlich schützen.','Den CP für den Abschluss morgen behalten.','Den CP für beliebigen Zusatzschaden nutzen.'],1,'Heute1 erwarteter Punkt (0,25×4), morgen2 sichere Punkte. Der gewünschte Zeithorizont umfasst beide Züge; „jetzt kann ich es einsetzen“ ist kein Wertmaßstab.')
tactic('h07','hard','Du kannst eine gegnerische Aktion mit100% für3 Punkte stoppen oder ein zweites Ziel mit70% nehmen: Bei Erfolg bekommst du3 eigene Punkte und verhinderst2 gegnerische. Scheitern kostet keine zusätzlichen Punkte. Keine Limits greifen. Welche Route maximiert die erwartete Differenz?', ['Die sichere Aktionsunterbrechung nehmen.','Beide Ziele mit unberechneter Hälfte angehen.','Den zweiten Zielwechsel mit70% versuchen.'],2,'Sicherer Denial:3. Zielwechsel:0,70×(3+2)=3,5. Dieser Vorteil hängt ausdrücklich daran, dass der Fehlschlag laut Aufgabe keine zusätzlichen Kosten hat.')
tactic('h08','hard','Zug4: Ein flankierender Trupp darf jetzt für5 sichere Punkte geopfert werden. Erhalten bleibt er heute punktlos, sichert aber Zug5 mit80% sechs Punkte. Die gegnerische Schlusswertung wird davon nicht verändert. Welcher Weg erzielt mehr erwartete eigene Punkte?', ['Die fünf Punkte heute nehmen.','Den Trupp für Zug5 erhalten.','Den Trupp ohne weitere Aufgabe verstecken.'],0,'Fünf jetzt sind höher als0,80×6=4,8 später. Ressourcenerhalt ist kein Selbstzweck; bei anderer Gewinnschwelle oder Gegnerschlusswertung könnte die Abwägung anders ausfallen.')
tactic('h09','hard','Du hast zwei Angreifer. X allein entfernt einen Halter mit90%, Y allein mit60%, gemeinsam sicher. Du kannst X erst nach Y aktivieren. Y hat keine andere Aufgabe; X kann bei nicht benötigter Unterstützung sicher4 Punkte an anderer Stelle ermöglichen. Welche Sequenz?', ['X und Y sofort auf den Halter festlegen.','Y zuerst; X nur bei dessen Fehlschlag nutzen.','X zuerst; Y danach ohne andere Aufgabe nutzen.'],1,'Y bekommt zuerst die60%-Chance. In diesen60% bleibt X für4 Punkte frei; in den übrigen Fällen unterstützt X. Die Sequenz hält einen wertvollen Folgeentscheid offen, statt Ressourcen vorzeitig zu binden.')
tactic('h10','hard','Du spielst zuerst in Runde5. Position A bringt jetzt5 und verliert durch den letzten Gegnerzug sicher einen Spielendbonus von5. Position B bringt jetzt3 und behält den Bonus sicher. Andere Wertungen sind gleich. Welche Position liefert insgesamt mehr?', ['Die frühe Fünf-Punkte-Position A.','Die frühe Drei-Punkte-Position B.','Beide Positionen ohne Besetzung lassen.'],1,'A bringt5 insgesamt, B3+5=8. Die eigene End-of-Turn-Wertung und die spätere End-of-Battle-Wertung sind unterschiedliche Zeitpunkte.')
tactic('h11','hard','Ein gefährlicher Panzer kann deine Halter nur durch einen engen, legal blockierbaren Endpositionsbereich erreichen. Dein kleiner Screen blockiert diesen Bereich sicher, verursacht aber keinen Schaden. Alternativ schießt er mit30% auf einen Panzer-Kill; bei Fehlschlag verlierst du6 Punkte. Der Kill bringt keine eigenen Punkte. Welche Wahl ist vorzuziehen?', ['Den Panzer-Kill mit dem Screen versuchen.','Den Screen am ungefährlichen Heimziel lassen.','Den maßgeblichen Endpositionsbereich blockieren.'],2,'Die Aufgabenannahme bestätigt die wirksame Blockade ausdrücklich; sie verhindert den Punkteverlust sicher. Eine beliebige Infanterielinie wäre gegen manche Modelle keine legale Sperre – das wird hier nicht als Regelfalle versteckt.')
tactic('h12','hard','Du kannst X für4 sichere Differenzpunkte entfernen oder Y mit75%: Y verhindert im Erfolgsfall4 gegnerische Punkte und öffnet2 eigene; bei Fehlschlag verliert dein Helfer sicher1 Punkt. Welcher Angriff maximiert den Erwartungswert?', ['Den Angriff auf Y durchführen.','Den Angriff auf X durchführen.','Beide Angriffseinheiten zurückhalten.'],0,'Y:0,75×6−0,25×1=4,25. X:4. Der knappe Vorsprung gilt für den Erwartungswert; bei einer konkreten Siegschwelle kann X die bessere risikoarme Wahl sein.')
